public class TextNodeTest {

    @Test
    public void constructorTest() {
        String text = "Hello World";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.text());
    }

    @Test
    public void nodeNameTest() {
        TextNode textNode = new TextNode("test");
        assertEquals("Text", textNode.nodeName());
    }

    @Test
    public void textTest() {
        String text = "Hello World";
        TextNode textNode = new TextNode(text);
        assertEquals("Hello World", textNode.text());

        textNode = new TextNode();
        assertNull(textNode.text());
    }

    @Test
    public void textSetTest() {
        String text = "Hello World";
        TextNode textNode = new TextNode();
        textNode.text(text);
        assertEquals(text, textNode.text());
    }

    @Test
    public void getWholeTextTest() {
        String text = "Hello\nWorld";
        TextNode textNode = new TextNode(text);
        assertEquals("Hello\nWorld", textNode.getWholeText());

        text = "Hello World";
        textNode = new TextNode();
        assertNull(textNode.getWholeText());
    }

    @Test
    public void isBlankTest() {
        String text = "";
        TextNode textNode = new TextNode(text);
        assertTrue(textNode.isBlank());

        text = "   ";
        textNode = new TextNode(text);
        assertTrue(textNode.isBlank());

        text = "Hello World";
        textNode = new TextNode(text);
        assertFalse(textNode.isBlank());
    }

    @Test
    public void splitTextTest() {
        String text = "Hello\nWorld";
        TextNode textNode = new TextNode(text);

        int offset1 = 0;
        TextNode nodeAfterOffset1 = textNode.splitText(offset1);
        assertEquals("Hello", nodeAfterOffset1.text());

        int offset2 = 6;
        TextNode nodeAfterOffset2 = textNode.splitText(offset2);
        assertEquals("World\n", nodeAfterOffset2.getWholeText());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String text = "\t\tHello World";
        String expectedNormalisedText = "   Hello World";

        String actualNormalisedText = TextNode.normaliseWhitespace(text);
        assertEquals(expectedNormalisedText, actualNormalisedText);

        text = "  ";
        expectedNormalisedText = " ";

        actualNormalisedText = TextNode.normaliseWhitespace(text);
        assertEquals(expectedNormalisedText, actualNormalisedText);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String text = "\t\tHello World";
        String expectedStripPEDText = "  Hello World";

        String actualStripPEDText = TextNode.stripLeadingWhitespace(text);
        assertEquals(expectedStripPEDText, actualStripPEDText);

        text = "   ";
        expectedStripPEDText = "";

        actualStripPEDText = TextNode.stripLeadingWhitespace(text);
        assertEquals(expectedStripPEDText, actualStripPEDText);
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        StringBuilder sb1 = new StringBuilder("\t");
        assertTrue(TextNode.lastCharIsWhitespace(sb1));

        StringBuilder sb2 = new StringBuilder(" ");
        assertTrue(TextNode.lastCharIsWhitespace(sb2));
        assertFalse(TextNode.lastCharIsWhitespace(sb2, 0));

        StringBuilder sb3 = new StringBuilder("");
        assertFalse(TextNode.lastCharIsWhitespace(sb3));
    }
}
